var WAVE_DIFF = [1.46, 1.83, 1.9, 1.75, 2.64, 3.6, 1.9, 2.2, 3.6, 1.05, 4.6, 1.05, 2.2, 4.2, 1.6, 4.4, 1.1, 2.5, 2.74, 2.3, 0.6];
var ENDLESS_DIFF = 2.3;
var ENDLESS_POOL = ["rampelin", "essaim", "coureur", "cuirasse", "tireur", "mage_fele", "bete_runique", "brecheur", "invocateur"];
var ENDLESS_BOSSES = ["brute", "alpha_runique", "gardien_basalte", "ingenieur_fele"];
function waveToughness(n) {
  if (n <= WAVES.length) return 1.2 + 0.36 * (n - 1);
  return Math.max(1.2 + 0.36 * (n - 1), getWave(n).hpMul * 0.8);
}
function getWave(n) {
  if (n <= WAVES.length) {
    const w = WAVES[n - 1], k2 = WAVE_DIFF[n - 1];
    return { ...w, hpMul: w.hpMul * k2, dmgMul: w.dmgMul * k2 };
  }
  const k = n - WAVES.length;
  const a = ENDLESS_POOL[n * 3 % ENDLESS_POOL.length];
  const b = ENDLESS_POOL[(n * 5 + 2) % ENDLESS_POOL.length];
  const boss = k % 5 === 0;
  const groups = [{ enemy: a, count: 10 }, { enemy: b, count: 8 }];
  if (boss) groups.push({ enemy: ENDLESS_BOSSES[k / 5 % ENDLESS_BOSSES.length], count: 1 + Math.floor(k / 10) });
  const m = 3.4 * ENDLESS_DIFF * Math.pow(1.13, k);
  return { n, name: t("Faille {0}", n), groups, hpMul: m, dmgMul: Math.sqrt(m) * 1.3, danger: boss ? t("Mini-boss en renfort !") : t("La faille s'\xE9largit\u2026"), boss };
}
